using System.Text;
using GcodeAnalyzer.Core;

namespace GcodeAnalyzer.Tests;

// Kopfzeilen und Markierungen nachgebildet, nicht aus echten Dateien dieser Slicer.
public class SlicerTests
{
    static AnalysisResult Snippet(string gcode) =>
        GcodeAnalysis.Analyze(new MemoryStream(Encoding.UTF8.GetBytes(gcode)), "snippet.gcode");

    const string Square = """
        G1 X0 Y0 E1
        G1 X10 Y0 E1
        G1 X10 Y10 E1
        G1 X0 Y10 E1
        """;

    [Fact]
    public void PrusaSlicer()
    {
        var r = Snippet($"""
            ; generated by PrusaSlicer 2.8.1+win64 on 2024-10-01 at 10:00:00 UTC
            M83
            ;LAYER_CHANGE
            ;Z:0.2
            ;HEIGHT:0.2
            G1 X0 Y-1 Z0.2
            ;TYPE:External perimeter
            {Square}
            ;TYPE:Internal infill
            G1 X5 Y5 E1
            ; filament used [mm] = 1234.5
            ; total filament used [g] = 3.7
            ; total filament cost = 0.1
            ; estimated printing time (normal mode) = 1h 2m 3s
            ; perimeters = 2
            ; external_perimeter_extrusion_width = 112.5%
            ; perimeter_extrusion_width = 0
            ; extrusion_width = 0.45
            ; nozzle_diameter = 0.4
            ; fill_density = 15%
            ; fill_pattern = gyroid
            ; top_one_perimeter_type = topmost
            ; support_material = 0
            ; slowdown_below_layer_time = 5
            ; bed_shape = 0x0,250x0,250x210,0x210
            """);
        Assert.Equal(("PrusaSlicer", "2.8.1+win64"), (r.SlicerName, r.SlicerVersion));
        Assert.Empty(r.Warnings);
        Assert.Equal(new TimeSpan(1, 2, 3), r.EstimatedTime);
        Assert.Equal(3.7, r.FilamentWeightG);
        Assert.Equal(2, r.Walls.TargetLoops);
        Assert.Equal(0.45, r.Walls.OuterWidth, 3);   // 112,5 % von 0,4
        Assert.Equal(0.45, r.Walls.InnerWidth, 3);   // 0 = automatisch, extrusion_width
        Assert.Equal(15, r.InfillDensity);
        Assert.Equal(5, r.MinLayerTime);
        Assert.Equal((0f, 0f, 250f, 210f), r.Bed);
        Assert.Contains(PathCategory.OuterWall, r.Layers[0].Segments.Select(s => s.Category));
        Assert.Contains(PathCategory.SparseInfill, r.Layers[0].Segments.Select(s => s.Category));
    }

    [Fact]
    public void BambuStudio()
    {
        var r = Snippet($"""
            ; HEADER_BLOCK_START
            ; BambuStudio 01.09.00.70
            ; model printing time: 1h 10m 41s; total estimated time: 1h 17m 20s
            ; total layer number: 2
            ; total filament weight [g] : 11.62
            ; HEADER_BLOCK_END
            M83
            ; CHANGE_LAYER
            ; Z_HEIGHT: 0.2
            ; LAYER_HEIGHT: 0.2
            G1 X0 Y-1 Z0.2
            ; FEATURE: Outer wall
            {Square}
            ; CHANGE_LAYER
            ; Z_HEIGHT: 0.4
            ; LAYER_HEIGHT: 0.2
            G1 Z0.4
            ; FEATURE: Sparse infill
            G1 X5 Y5 E1
            """);
        Assert.Equal(("BambuStudio", "01.09.00.70"), (r.SlicerName, r.SlicerVersion));
        Assert.Empty(r.Warnings);
        Assert.Equal(new TimeSpan(1, 17, 20), r.EstimatedTime);
        Assert.Equal(11.62, r.FilamentWeightG);
        Assert.Equal(2, r.LayerCount);
        Assert.Equal(0.4f, r.Layers[1].Z);
        Assert.Equal(PathCategory.OuterWall, r.Layers[0].Segments.First(s => s.Extrusion > 0).Category);
        Assert.Equal(PathCategory.SparseInfill, r.Layers[1].Segments.Last().Category);
    }

    [Fact]
    public void CuraIsReadWithWarning()
    {
        var r = Snippet("""
            ;FLAVOR:Marlin
            ;Generated with Cura_SteamEngine 5.7.0
            M83
            ;LAYER:0
            G1 X0 Y0 Z0.2
            G1 X10 Y0 E1
            ;LAYER:1
            G1 Z0.4
            G1 X10 Y10 E1
            """);
        Assert.Equal("Cura_SteamEngine", r.SlicerName);
        Assert.Equal(2, r.LayerCount);
        Assert.Equal(0.4f, r.Layers[1].Z);
        Assert.Contains(r.Warnings, w => w.Contains("nicht unterstützt"));
    }

    [Fact]
    public void MultipleFilamentsGiveWarningAndResult()
    {
        var r = Snippet("; generated by OrcaSlicer 2.4.2 on x\nM83\nT0\nG1 X0 Y0 Z0.2\nG1 X10 Y0 E1\nT1\nG1 X10 Y10 E1\n");
        Assert.Contains(r.Warnings, w => w.Contains("Mehrere Filamente"));
        Assert.Equal(2, r.Layers.Single().Segments.Length);
    }

    [Fact]
    public void GarbageGivesWarningInsteadOfCrash()
    {
        var bytes = new byte[50_000];
        new Random(1).NextBytes(bytes);
        var r = GcodeAnalysis.Analyze(new MemoryStream(bytes), "kaputt.gcode");
        Assert.Equal(0, r.LayerCount);
        Assert.Contains(r.Warnings, w => w.Contains("Keine Druckbewegungen"));
    }

    [Fact]
    public void BrokenNumbersAreIgnored()
    {
        var r = Snippet("; printable_area = 0x0,abcx0,220x220\nG1 Xfoo Y1 E\nG1 X1 Y1 Z0.2\nG1 X2 Y1 E1 F-\n");
        Assert.Single(r.Layers);
    }
}
